  cy.get('#emojiPickerSearch').should('have.attr', 'aria-label', 'Search for an emoji');
  // # Focus on the first emoji Category
  cy.get('#emojiPickerCategories').children().eq(0).focus().tab({
    shift: true
  }).tab();
  const categories = [{
    ariaLabel: 'Smileys & Emotion',
    header: 'Smileys & Emotion'
  }, {
    ariaLabel: 'People & Body',
    header: 'People & Body'
  }, {
    ariaLabel: 'Animals & Nature',
    header: 'Animals & Nature'
  }, {
    ariaLabel: 'Food & Drink',
    header: 'Food & Drink'
  }, {
    ariaLabel: 'Travel Places',
    header: 'Travel Places'
  }, {
    ariaLabel: 'Activities',
    header: 'Activities'
  }, {
    ariaLabel: 'Objects',
    header: 'Objects'
  }, {
    ariaLabel: 'Symbols',
    header: 'Symbols'
  }, {
    ariaLabel: 'Flags',
    header: 'Flags'
  }];
  // * Verify if emoji Categories gets the focus when tab is pressed
  cy.get('#emojiPickerCategories').children('.emoji-picker__category').each(($el, index) => {
    // * Verify each category
    if (index < categories.length) {
      // * Verify accessibility support in emoji category
      cy.get($el).should('have.class', 'a11y--active a11y--focused').should('have.attr', 'aria-label', categories[index].ariaLabel);
