      verifyArrowKeysEmojiNavigation('{rightarrow}', 3);
      verifyArrowKeysEmojiNavigation('{leftarrow}', 2);
      // # Press tab
      cy.get($el).focus().tab();
    }
  });
  // # Close the Emoji Popover
  cy.get('body').click();
});

