    });
    cy.get('.active').find('#sidebarItem_' + favPublicChannels[0].name).should('exist');
    // # No navigation - stay in place
    cy.get('body').type('{alt}{shift}', {
      release: false
    }).type('{uparrow}').type('{alt}{shift}', {
      release: true
    });
